const createReportId = () => (globalThis.crypto?.randomUUID?.() || `${Date.now().toString(36)}-${Math.random().toString(36).slice(2, 10)}`);
const formatReportDate = (report, locale = 'en') => { const date = report?.createdAt ? new Date(report.createdAt) : new Date(report?.date || Date.now()); return Number.isNaN(date.getTime()) ? String(report?.date || '—') : new Intl.DateTimeFormat(locale === 'az' ? 'az-Latn-AZ' : locale === 'ru' ? 'ru-RU' : 'en-US', { dateStyle: 'medium', timeStyle: 'short' }).format(date); };
const downloadRowsAsCsv = (rows, filename) => { const csv = rows.map(row => row.map(value => `"${String(value ?? '').replaceAll('"','""')}"`).join(',')).join('\r\n'); const blob = new Blob([`\uFEFF${csv}`], { type: 'text/csv;charset=utf-8' }); const url = URL.createObjectURL(blob); const a = document.createElement('a'); a.href = url; a.download = filename; a.click(); window.setTimeout(() => URL.revokeObjectURL(url), 1000); };
async function fetchWithTimeout(url, timeoutMs = 25000, timeoutMessage = 'Request timed out.') { const controller = new AbortController(); const timer = window.setTimeout(() => controller.abort(), timeoutMs); try { return await fetch(url, { signal: controller.signal }); } catch (error) { if (error?.name === 'AbortError') throw new Error(timeoutMessage); throw error; } finally { window.clearTimeout(timer); } }
function go(route) {
  const next = `#/${route}`;
  if (window.location.hash === next) window.dispatchEvent(new HashChangeEvent('hashchange'));
  else window.location.hash = next;
}
function readRoute() { const raw = (window.location.hash.replace(/^#\/?/, '') || 'home').split('?')[0]; return ['detective','detective/hotspots','hotspots'].includes(raw) ? 'trend' : raw; }
export default function App() {
  const [route, setRoute] = useState(readRoute);
  useEffect(() => {
    const onHash = () => setRoute(readRoute());
    window.addEventListener('hashchange', onHash);
    return () => window.removeEventListener('hashchange', onHash);
  }, []);
  useEffect(() => {
    const publicRoutes = ['home','features','about','contact','login','signup'];
    if (!publicRoutes.includes(route)) {
      let session = null;
      try { session = JSON.parse(localStorage.getItem('tomorrowproof-demo-user') || 'null'); } catch { session = null; }
      if (!session) go('login');
    }
  }, [route]);
  if (route === 'login' || route === 'signup') return <AuthPage mode={route} />;
  if (route === 'home' || route === 'features' || route === 'about' || route === 'contact') return <Landing route={route} />;
  return <TomorrowproofApp route={route} />;
}
