function DashboardPage({ projects, reports, analysisRuns, onCreate, onOpenProjects, onOpenLab, onOpenTrend, onOpenReports }) {
  const analysed = projects.filter(p => reports.some(r => r.projectId === p.id && r.kind === 'building-screening')).length;
  const awaiting = projects.length - analysed;
  return <section className="dashboard-panel app-white-panel">
    <div className="dashboard-heading"><div><h1>Dashboard</h1><p>Assess building performance under future climate stress in Azerbaijan.</p></div><button className="primary-app-button" onClick={onCreate}><Plus size={15}/> Create New Project</button></div>
    <div className="dashboard-stats">
      <Stat label="Your projects" value={projects.length} note="Saved in this browser workspace"/>
      <Stat label="Analysis runs" value={analysisRuns} note="Saved analysis runs in this workspace"/>
      <Stat label="Analysed projects" value={analysed} note="Completed or partially completed runs on this page"/>
      <Stat label="Awaiting setup" value={awaiting} note="Projects on this page"/>
    </div>
    <div className="dashboard-workflow"><button onClick={onCreate}><span>01</span><b>Create a project</b><small>Save a building and its location</small><em>Start here <ArrowRight size={13}/></em></button><button onClick={onOpenLab}><span>02</span><b>Run building screening</b><small>Fetch NASA POWER historical baseline</small><em>Open climate lab <ArrowRight size={13}/></em></button><button onClick={onOpenTrend}><span>03</span><b>Explore climate trends</b><small>Review historical indicators by location</small><em>Open trend analysis <ArrowRight size={13}/></em></button><button onClick={onOpenReports}><span>04</span><b>Review reports</b><small>Use saved results and export protocols</small><em>View reports <ArrowRight size={13}/></em></button></div>
    <div className="active-project-head"><div><h2>Your Building Assessments</h2><p>{projects.length} saved projects</p></div>{projects.length > 0 && <button className="text-button" onClick={onOpenProjects}>View all <ChevronRight size={14}/></button>}</div>
    {projects.length === 0 ? <button className="empty-create-card" onClick={onCreate}><span className="big-plus"><Plus size={24}/></span><b>Create a new project</b><small>Save a project, then set its site and<br/> boundary.</small></button> : <div className="project-card-grid">{projects.slice(0,4).map(p => <article className="mini-project-card" key={p.id}><span className="mini-project-icon"><FolderOpen size={19}/></span><div><b>{p.name}</b><small>{p.location || 'Location not set'} · {p.created}</small></div><span className="project-status">{p.status || 'Setup'}</span></article>)}<button className="add-project-mini" onClick={onCreate}><Plus size={17}/> New project</button></div>}
  </section>;
}
function Stat({ label, value, note }) { return <article className="stat-card"><span>{label}</span><b>{value}</b><small>{note}</small></article>; }
function ProjectsPage({ projects, onCreate, onOpenTrend }) {
  return <section className="app-white-panel standard-page"><div className="page-title-row"><div><h1>Projects</h1><p>Manage your urban design projects and site boundaries.</p></div><button className="primary-app-button" onClick={onCreate}><Plus size={15}/> Create New Project</button></div>
    {projects.length ? <div className="project-list">{projects.map(p => <article className="project-list-row" key={p.id}><div className="folder-tile"><Folder size={22}/></div><div className="project-list-main"><b>{p.name}</b><span>{p.location || 'Location not set'} · Created {p.created}</span></div><span className="status-chip">{p.status || 'Awaiting setup'}</span><button className="outline-button" onClick={onOpenTrend}>Run analysis <ArrowRight size={14}/></button></article>)}</div> : <EmptyState icon={<Folder size={25}/>} title="No projects yet" text="Create a project to save a site, define its boundary, and start your analysis." action="Create New Project" onAction={onCreate}/>}</section>;
}
