    en: { title: 'Saved Analyses', subtitle: 'Persistent research history for building screenings and climate investigations.', total: 'Total analyses', recent: 'Recent assessments', buildings: 'Saved buildings', trends: 'Climate trends', latest: 'Last analysis', search: 'Search by building, place or report ID…', all: 'All analysis types', building: 'Building screening', trend: 'Climate trend', newest: 'Newest first', oldest: 'Oldest first', start: 'From date', end: 'To date', compare: 'Compare selected', exportAll: 'Export all CSV', open: 'Open full report', duplicate: 'Duplicate building', export: 'Export CSV', remove: 'Delete', no: 'No saved analyses match these filters', none: 'Run a building screening or historical trend to create your first saved analysis. Reports remain in this browser profile and are restored after a restart.', back: 'Back to saved analyses', pdf: 'Print / Save PDF', source: 'Data source & limitations', metrics: 'Original indicators', recommendations: 'Original recommendations', profile: 'Saved building profile', date: 'Analysis date', id: 'Report ID', location: 'Location', horizon: 'Climate horizon', score: 'Screening score', type: 'Analysis type', comparison: 'Comparison of saved reports', selectHint: 'Select at least two analyses to compare them.', monthly: 'Historical monthly observations', annual: 'Annual historical trend', sourceNASA: 'NASA POWER historical regional-grid data', assumptions: 'Scenario assumptions', limitations: 'Scientific limitations', variables: 'Saved values', closeCompare: 'Close comparison', selectAll: 'Select all', clear: 'Clear', buildingProject: 'Building / project', buildingType: 'Building type', construction: 'Construction system', roof: 'Roof finish', latitude: 'Latitude', longitude: 'Longitude', meanT: 'Historical mean T2M_MAX', scenario: 'Illustrative scenario stress', humidity: 'Relative humidity baseline', precipitation: 'Precipitation baseline', solar: 'Solar radiation baseline', heuristic: 'Heuristic screening score', dataset: 'Dataset', parameters: 'Parameters', period: 'Period', processing: 'Processing method', recommendationsNote: 'Recommendations were not included in this older snapshot.', tryFilters: 'Try changing the search, dates or analysis type.', selected: 'selected', persistentNote: 'Persistent saved snapshots', recentNote: 'Reports created in the last 30 days', buildingNote: 'Unique buildings in saved reports', trendNote: 'Historical trend investigations', latestNote: 'Original report creation time', compareLabel: 'Compare', year: 'Year', month: 'Month', value: 'Value'  },
